<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {session,logout,clearSession,ApiError} from '../auth'
const route=useRoute(),router=useRouter(),menuOpen=ref(false),wallets=ref<any[]>([]),wallet=ref(''),side=ref('BUY'),price=ref(''),size=ref(''),book=ref<any>(null),preview=ref<any>(null),context=ref<any>(null),message=ref(''),busy=ref(false),result=ref<any>(null),pending=ref<any>(null),clearAcknowledged=ref(false)
let draftRevision=0,loadRevision=0
const pendingKey='polysports_pending_order'
const stateName=(s:string)=>({submitting:'提交中',pending:'已接受，待核对',partially_filled:'部分成交',filled:'全部成交',rejected:'已拒绝',cancelled:'已撤单',unknown:'结果未知'} as Record<string,string>)[s]||'未知'
const errorName=(s:string)=>({engine_restarting:'撮合引擎正在重启，系统未自动重发',post_only_mode:'市场处于 post-only 模式，系统未自动改变或重发订单',signed_order_mismatch:'签名参数不一致，订单未发送'} as Record<string,string>)[s]||s
const time=(v:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v))
async function api(path:string,options:RequestInit={}){const response=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store',...options});const body=await response.json();if(!response.ok)throw new Error(body?.error?.message||'请求失败');return body.data}
async function load(){const generation=++loadRevision;const link=route.params.link,outcome=route.params.outcome;try{const [w,b,c]=await Promise.all([api('/wallets'),api('/outcomes/'+outcome+'/book'),api('/order-context/'+link+'/'+outcome)]);if(generation!==loadRevision)return;wallets.value=w.items;book.value=b;context.value=c;if(wallets.value.length)wallet.value=wallets.value[0].id}catch{if(generation===loadRevision)message.value='钱包或真实盘口不可用，请检查配置后重试。'}}
async function makePreview(){busy.value=true;message.value='';preview.value=null;const revision=draftRevision;const snapshot=context.value?{...context.value}:null;const draft={wallet_id:wallet.value,market_link_id:route.params.link,outcome_id:route.params.outcome,side:side.value,limit_price:price.value,size:size.value};try{const data=await api('/single-orders/preview',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify(draft)});if(revision!==draftRevision){message.value='参数已变化，请重新预览。';return}preview.value={...data,context_snapshot:snapshot}}catch(e){message.value=e instanceof Error?e.message:'预览失败。'}finally{busy.value=false}}
async function submit(){if(!preview.value||busy.value||pending.value)return;busy.value=true;message.value='';const key=crypto.randomUUID();const payload={wallet_id:preview.value.wallet_id,market_link_id:preview.value.market_link_id,outcome_id:preview.value.outcome_id,side:preview.value.side,limit_price:preview.value.limit_price,size:preview.value.size,preview_token:preview.value.preview_token};pending.value={key,wallet_id:payload.wallet_id};try{localStorage.setItem(pendingKey,JSON.stringify(pending.value))}catch{pending.value=null;busy.value=false;message.value='无法保存查询凭据，订单未提交。';return}try{const data=await api('/single-orders',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf,'Idempotency-Key':key},body:JSON.stringify(payload)});result.value=data.intent;if(!['unknown','submitting'].includes(data.intent.state)){localStorage.removeItem(pendingKey);pending.value=null}message.value='订单已记录；请查看状态，接受不代表成交。'}catch{message.value='提交结果未确认，请使用原幂等键查询，不要重新下单。'}finally{busy.value=false}}
async function lookup(){if(!pending.value)return;try{result.value=await api('/trade-intents/by-key/'+pending.value.key+'?wallet_id='+encodeURIComponent(pending.value.wallet_id));if(!['unknown','submitting'].includes(result.value.state)){localStorage.removeItem(pendingKey);pending.value=null}message.value='已查询现有订单状态。'}catch{message.value='尚无法确认订单是否创建，请稍后再次查询。'}}
function clearPending(){if(!clearAcknowledged.value)return;localStorage.removeItem(pendingKey);pending.value=null;clearAcknowledged.value=false;message.value='本机记录已清除，服务端订单状态不受影响。'}
async function signOut(){try{await logout();await router.replace('/login')}catch(e){if(e instanceof ApiError&&e.status===401){clearSession();await router.replace('/login')}else message.value='退出请求未确认，请重试。'}}
onMounted(()=>{try{pending.value=JSON.parse(localStorage.getItem(pendingKey)||'null')}catch{pending.value=null}})
watch([wallet,side,price,size],()=>{draftRevision++;preview.value=null},{flush:'sync'})
watch(()=>[route.params.link,route.params.outcome],()=>{draftRevision++;preview.value=null;context.value=null;book.value=null;result.value=null;load()},{immediate:true})
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand"><span class="brand-mark">P</span> PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand"><span class="brand-mark">P</span> PolySports</div><p class="nav-label">工作台</p><nav aria-label="主导航"><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><span aria-disabled="true">组合交易 <small>即将开放</small></span><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace"><div class="workspace-top"><span class="breadcrumb">工作台 / 单场订单</span><div class="account"><span>{{session.username}}</span><button class="text-button" @click="signOut">退出</button></div></div><div class="page-heading"><div><p class="eyebrow">REAL FUNDS</p><h1>单场订单预览</h1><p class="muted">确认后将使用真实资金提交限价单；订单接受不等于成交。</p></div></div><p role="status" class="form-message">{{message}}</p><section v-if="pending" class="welcome-card"><h2>有一笔结果待核对</h2><p>系统保留了原幂等键。查询结果前请勿重复下单。</p><button class="text-button" @click="lookup">按原键查询</button><p>仅在已到 Polymarket 独立核实、并理解重复下单风险后，才清除本机记录。</p><label><input v-model="clearAcknowledged" type="checkbox">我已独立核实订单状态</label><button class="text-button" :disabled="!clearAcknowledged" @click="clearPending">清除本机记录</button></section><section class="welcome-card detail"><p v-if="context">{{context.home}} 对 {{context.away}} · {{context.market_question}} · 选项：{{context.outcome_label}} · {{time(context.starts_at)}} UTC+8</p><p v-if="context" class="id-text">资产 ID：{{context.asset_id}} · 协议：{{context.protocol_version}}</p><p v-if="book">价格增量 {{book.tick_size}} · 最小份额 {{book.min_order_size}} · 盘口时间 {{book.observed_at}}</p><p v-else>真实盘口不可用。</p><form @submit.prevent="makePreview"><label for="wallet">钱包</label><select id="wallet" v-model="wallet" required @change="preview=null"><option v-for="w in wallets" :key="w.id" :value="w.id">{{w.label}} · {{w.wallet_address}}</option></select><label for="side">方向</label><select id="side" v-model="side" @change="preview=null"><option value="BUY">买入</option><option value="SELL">卖出</option></select><label for="price">限价</label><input id="price" v-model="price" inputmode="decimal" required @input="preview=null"><label for="size">份额</label><input id="size" v-model="size" inputmode="decimal" required @input="preview=null"><button class="text-button" :disabled="busy || !wallet || !book">验证并预览</button></form></section><section v-if="preview" class="welcome-card detail"><h2>确认真实资金订单</h2><p>钱包：{{wallets.find(w=>w.id===preview.wallet_id)?.label}} · {{wallets.find(w=>w.id===preview.wallet_id)?.wallet_address}}</p><p v-if="preview.context_snapshot">{{preview.context_snapshot.home}} 对 {{preview.context_snapshot.away}} · {{preview.context_snapshot.market_question}} · {{preview.context_snapshot.outcome_label}} · {{time(preview.context_snapshot.starts_at)}} UTC+8</p><p>方向：{{preview.side}} · 价格：{{preview.limit_price}} · 份额：{{preview.size}}</p><p>限价金额：{{preview.estimated_notional}} pUSD；手续费未知，实际成交以交易所记录为准。</p><p>预览有效期至 {{preview.expires_at}}；提交时将再次检查盘口和钱包。</p><button class="text-button" :disabled="busy || !!pending" @click="submit">确认并提交真实订单</button></section><section v-if="result" class="welcome-card detail"><h2>订单状态</h2><p>状态：{{stateName(result.state)}} · 已成交份额：{{result.matched_size ?? '未知'}}</p><p v-if="result.error_code">状态说明：{{errorName(result.error_code)}}</p><p v-if="result.retry_after_seconds!=null">建议等待：{{result.retry_after_seconds}} 秒</p><RouterLink to="/orders">查看交易记录</RouterLink></section></main></div></template>
